<?php ac_hero('Two-person operation','Operator Outputs','Generate run sheet, emergency sheet, packing list, rehearsal checklist, rig patch quick reference, and recovery notes with source IDs preserved.'); $states=['blackout','safe work light','projection black','projection hold','fog off','strobes off','music stop','operator reset','performer safe look','costume-change hold look']; $operatorRecords=ac_records_for_operator_outputs(); ?><section class="panel"><h2>Emergency states</h2><div class="family-strip"><?php foreach($states as $s) echo ac_pill($s,'risk'); ?></div></section><section class="grid two"><article class="panel"><h2>Output checklist shells</h2><?php ac_checklist(['Run sheet','Emergency sheet','Packing list','Rehearsal checklist','Rig patch quick reference','Operator recovery notes']); ?></article><article class="panel"><h2>Rig patch records</h2><?php ac_record_cards(array_slice($operatorRecords,0,6)); ?></article></section><section class="panel"><h2>Operator / rig source records</h2><?php ac_filters(); ac_record_table($operatorRecords); ?></section>
